#!/usr/bin/env bash
# Populate the Samba AD DC: OU, groups (with a nested one), users, a service account,
# and a CA-signed server certificate with a SAN (Samba's own autogenerated certificate
# has no subjectAltName, which no verifying client accepts).
set -euo pipefail
C=${SAMBA_CONTAINER:-voltrus-sso-live-samba-1}
RUN=$(cd "$(dirname "$0")" && pwd)/.run
st() { docker exec "$C" samba-tool "$@"; }
mkdir -p "$RUN"

for _ in $(seq 60); do docker exec "$C" samba-tool domain info 127.0.0.1 >/dev/null 2>&1 && break; sleep 2; done

st ou create OU=Groups 2>/dev/null || true
st group add "SCADA Admins" --groupou=OU=Groups 2>/dev/null || true
st group add "SCADA Operators" --groupou=OU=Groups 2>/dev/null || true
st group add "SCADA Night Shift" --groupou=OU=Groups 2>/dev/null || true
st group addmembers "SCADA Operators" "SCADA Night Shift" 2>/dev/null || true   # nested group

mkuser() { st user create "$1" "$2" --given-name="$1" --surname=Live --mail-address="$1@corp.example" 2>/dev/null || st user setpassword "$1" --newpassword="$2" >/dev/null; }
mkuser alice 'Alice-Pw-1!'
mkuser bob 'Bob-Pw-1!'
mkuser carol 'Carol-Pw-1!'
mkuser dave 'Dave-Pw-1!'
st user create svc-voltrus 'Svc-Pass-1!' 2>/dev/null || st user setpassword svc-voltrus --newpassword='Svc-Pass-1!' >/dev/null   # CN=svc-voltrus (no given name)
st group addmembers "SCADA Admins" alice,dave 2>/dev/null || true
st group addmembers "SCADA Night Shift" bob 2>/dev/null || true
st user disable dave

# Server certificate: our own CA, SAN covers the names the tests dial.
if [ ! -f "$RUN/ldap-ca.pem" ]; then
  openssl req -x509 -newkey rsa:2048 -nodes -days 30 -subj "/O=Voltrus SSO live/CN=Voltrus live CA" \
    -keyout "$RUN/ldap-ca.key" -out "$RUN/ldap-ca.pem" 2>/dev/null
  openssl req -newkey rsa:2048 -nodes -subj "/CN=dc1.corp.example" -keyout "$RUN/dc.key" -out "$RUN/dc.csr" 2>/dev/null
  printf 'subjectAltName=DNS:dc1.corp.example,DNS:dc1.localhost,DNS:localhost,IP:127.0.0.1\nextendedKeyUsage=serverAuth\n' > "$RUN/san.ext"
  openssl x509 -req -in "$RUN/dc.csr" -CA "$RUN/ldap-ca.pem" -CAkey "$RUN/ldap-ca.key" -CAcreateserial \
    -days 30 -extfile "$RUN/san.ext" -out "$RUN/dc.pem" 2>/dev/null
fi
docker cp "$RUN/ldap-ca.pem" "$C":/var/lib/samba/private/tls/ca.pem
docker cp "$RUN/dc.pem" "$C":/var/lib/samba/private/tls/cert.pem
docker cp "$RUN/dc.key" "$C":/var/lib/samba/private/tls/key.pem
docker exec "$C" sh -c 'chown root:root /var/lib/samba/private/tls/*.pem && chmod 600 /var/lib/samba/private/tls/key.pem'
docker restart "$C" >/dev/null
for _ in $(seq 60); do docker exec "$C" samba-tool domain info 127.0.0.1 >/dev/null 2>&1 && break; sleep 2; done
echo "samba ready"
